    val SCOPE_SPAN = "In some cases, alternative word order can change the meaning entirely:\n* \u041d\u0435 \u043d\u0430\u0434\u043e \u043c\u0435\u043d\u044f \u0443\u0433\u043e\u0432\u0430\u0440\u0438\u0432\u0430\u0442\u044c. (\"No need me [to] persuade\" \u2192 One should not persuade me [''as I would never agree to do something''].)\n* \u041c\u0435\u043d\u044f \u043d\u0435 \u043d\u0430\u0434\u043e \u0443\u0433\u043e\u0432\u0430\u0440\u0438\u0432\u0430\u0442\u044c. (\"Me no need [to] persuade\" \u2192 There is no need to persuade me [''as I will do it anyway''].)"
    val PRONOUN_SPAN = "\u041e\u0431\u0440\u0430\u0437\u0443\u044e\u0442\u0441\u044f \u043e\u0442 [[\u0412\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0438\u043c\u0435\u043d\u0438\u0435|\u0432\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0438\u043c\u0435\u043d\u0438\u0439]] \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e [[\u041f\u0440\u0435\u0444\u0438\u043a\u0441 (\u0433\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u043a\u0430)|\u043f\u0440\u0435\u0444\u0438\u043a\u0441\u0430]] ''\u043d\u0438-'', ''\u043d\u0435-''<ref>{{\u041a\u043d\u0438\u0433\u0430|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u041b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0438 \u044f\u0437\u044b\u043a. \u0421\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u0438\u043b\u043b\u044e\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u044d\u043d\u0446\u0438\u043a\u043b\u043e\u043f\u0435\u0434\u0438\u044f|\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439=\u0413\u043e\u0440\u043a\u0438\u043d \u0410.\u041f.|\u0433\u043e\u0434=2006|\u044f\u0437\u044b\u043a=ru|\u043c\u0435\u0441\u0442\u043e=\u041c\u043e\u0441\u043a\u0432\u0430|\u0438\u0437\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e=\u0420\u043e\u0441\u043c\u0435\u043d|\u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b=611}}</ref>. \u041e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0441\u0442\u043e\u0438\u043c\u0435\u043d\u0438\u044f, \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043f\u0440\u0438\u0441\u0442\u0430\u0432\u043a\u043e\u0439 ''\u043d\u0435-'', \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043f\u0440\u0435\u0434\u0438\u043a\u0430\u0442\u0438\u0432\u043d\u044b\u043c\u0438<ref>{{\u041a\u043d\u0438\u0433\u0430|\u0430\u0432\u0442\u043e\u0440=\u041f\u0430\u0434\u0443\u0447\u0435\u0432\u0430 \u0415\u043b\u0435\u043d\u0430 \u0412\u0438\u043a\u0442\u043e\u0440\u043e\u0432\u043d\u0430|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u0420\u0443\u0441\u0441\u043a\u043e\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435|\u0438\u0437\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e=\u042f\u0437\u044b\u043a\u0438 \u0441\u043b\u0430\u0432\u044f\u043d\u0441\u043a\u043e\u0439 \u043a\u0443\u043b\u044c\u0442\u0443\u0440\u044b|\u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b=71|\u0441\u0442\u0440\u0430\u043d\u0438\u0446=303|isbn=978-5-9551-0657-1}}</ref>.\n\n== \u041f\u0440\u0438\u043c\u0435\u0440\u044b ==\n* \u0417\u0430 \u0443\u0442\u0435\u0440\u044e \u0448\u043b\u0435\u043c\u0430 \u0435\u0433\u043e '''''\u043d\u0438\u043a\u0442\u043e''''' '''''\u043d\u0435''''' \u0443\u043f\u0440\u0435\u043a\u043d\u0443\u043b, \u0438 \u043e\u043d \u043f\u043e\u0447\u0442\u0438 \u0443\u0441\u043f\u043e\u043a\u043e\u0438\u043b\u0441\u044f<ref name=\":0\">{{\u041a\u043d\u0438\u0433\u0430|\u0430\u0432\u0442\u043e\u0440=\u0412\u0430\u0441\u0438\u043b\u044c \u0411\u044b\u043a\u043e\u0432|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043a\u0440\u0438\u0433\u0441\u043c\u0430\u043d|\u0433\u043e\u0434=2002}}</ref>.\n* \u041d\u043e \u0441 \u044d\u0442\u0438\u043c \u043a\u043e\u043c\u0430\u043d\u0434\u0438\u0440\u043e\u043c, \u043f\u043e\u0436\u0430\u043b\u0443\u0439, '''''\u043d\u0438\u043a\u0430\u043a\u043e\u0433\u043e''''' \u043e\u0442\u0434\u044b\u0445\u0430 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0441\u044f<ref>{{\u041a\u043d\u0438\u0433\u0430|\u0430\u0432\u0442\u043e\u0440=\u0412\u0430\u0441\u0438\u043b\u044c \u0411\u044b\u043a\u043e\u0432|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u0411\u043e\u043b\u043e\u0442\u043e|\u0433\u043e\u0434=2001}}</ref>.\n* '''''\u041d\u0435\u0433\u0434\u0435''''' \u0442\u0430\u043c \u043a\u0443\u043f\u0430\u0442\u044c\u0441\u044f \u0438 \u0432\u0430\u043b\u044f\u0442\u044c\u0441\u044f, \u043e\u0434\u043d\u0438 \u043a\u0440\u0435\u043c\u043d\u0438 \u0434\u0430 \u043a\u043e\u043b\u044e\u0447\u043a\u0438<ref>{{\u041a\u043d\u0438\u0433\u0430|\u0430\u0432\u0442\u043e\u0440=\u0414\u043e\u043c\u0431\u0440\u043e\u0432\u0441\u043a\u0438\u0439 \u042e\u0440\u0438\u0439 \u041e\u0441\u0438\u043f\u043e\u0432\u0438\u0447|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u0424\u0430\u043a\u0443\u043b\u044c\u0442\u0435\u0442 \u043d\u0435\u043d\u0443\u0436\u043d\u044b\u0445 \u0432\u0435\u0449\u0435\u0439|\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439=\u0428\u0443\u0431\u0438\u043d\u0430 \u0415. \u0414.|\u0433\u043e\u0434=2011|\u0438\u0437\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e=\u0420\u0435\u0434\u0430\u043a\u0446\u0438\u044f \u0415\u043b\u0435\u043d\u044b \u0428\u0443\u0431\u0438\u043d\u043e\u0439|isbn=978-5-17-076318-4}}</ref>.\n* \u0410\u043f\u043b\u043e\u0434\u0438\u0441\u043c\u0435\u043d\u0442\u043e\u0432 \u0436\u0434\u0430\u0442\u044c \u043f\u043e\u043a\u0430 \u0447\u0442\u043e '''''\u043d\u0435\u043e\u0442\u043a\u0443\u0434\u0430'''''\u2026<ref>{{\u041a\u043d\u0438\u0433\u0430|\u0430\u0432\u0442\u043e\u0440=\u0421\u0435\u0440\u0433\u0435\u0439 \u0414\u043e\u0432\u043b\u0430\u0442\u043e\u0432|\u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435=\u041d\u0430\u0448\u0438|\u0433\u043e\u0434=1983}}</ref>\n\n{| class=\"wikitable\"\n![[\u0412\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0438\u043c\u0435\u043d\u0438\u0435]] \\\n[[\u041f\u0440\u0435\u0444\u0438\u043a\u0441 (\u0433\u0440\u0430\u043c\u043c\u0430\u0442\u0438\u043a\u0430)|\u043f\u0440\u0435\u0444\u0438\u043a\u0441]]\n!\u043d\u0438-\n!\u043d\u0435-\n|-\n|\u043a\u0442\u043e\n|\u043d\u0438\u043a\u0442\u043e\u0301\n|\u043d\u0435\u0