    val CONCORD_SPAN = "* \u041d\u0438\u043a\u0442\u043e \u043d\u0438\u043a\u043e\u043c\u0443 '''''\u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435''''' \u0441\u043a\u0430\u0437\u0430\u043b."
    val ADDRESS_SPAN = "\u0415\u0441\u0442\u044c \u043f\u043e\u043b\u043d\u044b\u0435 \u0438\u043c\u0435\u043d\u0430\u00a0\u2014 \u0418\u0440\u0438\u043d\u0430, \u0415\u0432\u0433\u0435\u043d\u0438\u044f, \u0410\u043b\u0435\u043a\u0441\u0430\u043d\u0434\u0440 \u0438 \u0434\u0440., \u0441\u043e\u043a\u0440\u0430\u0449\u0451\u043d\u043d\u044b\u0435 \u0438\u043b\u0438 \u043a\u0440\u0430\u0442\u043a\u0438\u0435 \u0438\u043c\u0435\u043d\u0430\u00a0\u2014 \u0418\u0440\u0430, \u0416\u0435\u043d\u044f, \u0421\u0430\u0448\u0430 \u0438 \u0434\u0440., \u0430 \u0442\u0430\u043a\u0436\u0435 \u0443\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u0435\u043b\u044c\u043d\u043e-\u043b\u0430\u0441\u043a\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435\u00a0\u2014 \u0418\u0440\u043e\u0447\u043a\u0430, \u0416\u0435\u043d\u0435\u0447\u043a\u0430, \u0421\u0430\u0448\u0435\u043d\u044c\u043a\u0430 \u0438 \u0434\u0440.\n\n\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043f\u043e [[\u041f\u043e\u043b\u043d\u043e\u0435 \u0438\u043c\u044f|\u043f\u043e\u043b\u043d\u043e\u043c\u0443 \u0438\u043c\u0435\u043d\u0438]] \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u043d\u043e \u0434\u043b\u044f \u043e\u0442\u0441\u0442\u0440\u0430\u043d\u0451\u043d\u043d\u043e-\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 \u043e\u0431\u0449\u0435\u043d\u0438\u044f, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0439 \u0438\u043b\u0438 \u043f\u043e\u043b\u0443\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u0431\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u043e\u0431\u0449\u0435\u043d\u0438\u044f, \u0432\u044b\u0440\u0430\u0436\u0430\u0435\u0442 \u043f\u043e\u0434\u0447\u0451\u0440\u043a\u043d\u0443\u0442\u043e \u0441\u0434\u0435\u0440\u0436\u0430\u043d\u043d\u043e\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u043a \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043d\u0438\u043a\u0443 \u0438 \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f, \u043a\u043e\u0433\u0434\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u043e\u0438\u0442 \u0441\u0435\u0440\u044c\u0451\u0437\u043d\u044b\u0439 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0437\u0430\u043c\u0435\u0447\u0430\u043d\u0438\u0435 \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043d\u0438\u043a\u0443: \u00ab\u0421\u0435\u0440\u0433\u0435\u0439, \u043c\u043d\u0435 \u043d\u0430\u0434\u043e \u0441 \u0442\u043e\u0431\u043e\u0439 \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c\u00bb, \u00ab\u0422\u0430\u0442\u044c\u044f\u043d\u0430, \u043f\u043e\u0434\u043e\u0439\u0434\u0438 \u0441\u044e\u0434\u0430\u00bb.\n\n\u041a\u0440\u0430\u0442\u043a\u0438\u0435 \u0444\u043e\u0440\u043c\u044b \u0438\u043c\u0451\u043d \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0432 \u0434\u0440\u0443\u0436\u0435\u0441\u043a\u0438-\u043d\u0435\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u043e\u0431\u0449\u0435\u043d\u0438\u0438 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c\u044b\u043c\u0438, \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0430\u043c\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0430"
    val AGO_SPAN = "He arrived in Moscow a week ago.<br />\u041e\u043d '''\u043f\u0440\u0438'''\u0435\u0445\u0430\u043b \u0432 \u041c\u043e\u0441\u043a\u0432\u0443 \u043d\u0435\u0434\u0435\u043b\u044e \u043d\u0430\u0437\u0430\u0434.\n| \u0432 / \u043d\u0430 + {{abbr|acc.|accusative}}<br />\u043a + {{abbr|dat.|dative}}<br />\u0438\u0437 / \u0441 / \u043e\u0442 + {{abbr|gen.|genitive}}\n|- style=\"vertical-align: top;\"\n| \u0443-<br />Intended departure, signals absence<br />Antonym: \u043f\u0440\u0438-\n| They will leave Vladivostok in a month.<br />\u041e\u043d\u0438 '''\u0443'''\u043b\u0435\u0442\u044f\u0442 \u0438\u0437 \u0412\u043b\u0430\u0434\u0438\u0432\u043e\u0441\u0442\u043e\u043a\u0430 \u0447\u0435\u0440\u0435\u0437 \u043c\u0435\u0441\u044f\u0446."
