        ),
        "relate events in time:</p>\n<table class=\"grid\" style=\"border-collapse: collapse;width: 100%;height: 91px\">\n<thead>\n<tr style=\"height: 15px\">\n<td style=\"width: 10.9543%;height: 15px;text-align: left\"><strong>Preposition</strong></td>\n<td style=\"width: 12.4453%;height: 15px\"><strong>Meaning</strong></td>\n<td style=\"width: 15.1291%;height: 15px\"><strong>Usage</strong></td>\n<td style=\"width: 41.4712%;height: 15px\"><strong>Example</strong></td>\n</tr>\n</thead>\n<tbody>\n<tr style=\"height: 15px\">\n<td style=\"width: 10.9543%;height: 15px\">\u041f\u0435\u0440\u0435\u0434</td>\n<td style=\"width: 12.4453%;height: 15px\">before</td>\n<td style=\"width: 15.1291%;height: 15px\">\u043f\u0435\u0440\u0435\u0434 + Instrumental</td>\n<td style=\"width: 41.4712%;height: 15px\">\u041f\u0435\u0440\u0435\u0434 \u0443\u0436\u0438\u043d\u043e\u043c \u043c\u044b \u0445\u043e\u0434\u0438\u043b\u0438 \u0432 \u043f\u0430\u0440\u043a.</td>\n</tr>\n<tr style=\"height: 15px\">\n<td style=\"width: 10.9543%;height: 15px\">\u041f\u043e\u0441\u043b\u0435</td>\n<td style=\"width: 12.4453%;height: 15px\">after</td>\n<td style=\"width: 15.1291%;height: 15px\">\u043f\u043e\u0441\u043b\u0435 + genitive</td>\n<td style=\"width: 41.4712%;height: 15px\">\u041f\u043e\u0441\u043b\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u044f \u0441\u043c\u043e\u0442\u0440\u0435\u043b\u0430 \u0444\u0438\u043b\u044c\u043c.</td>\n</tr>\n<tr style=\"height: 31px\">\n<td style=\"width: 10.9543%;height: 31px\">\u0427\u0435\u0440\u0435\u0437</td>\n<td style=\"width: 12.4453%;height: 31px\">in (a period of time)</td>\n<td style=\"width: 15.1291%;height: 31px\">\u0447\u0435\u0440\u0435\u0437 + genitive</td>\n<td style=\"width: 41.4712%;height: 31px\">\u041c\u044b \u0435\u0434\u0435\u043c \u0432 \u041b\u0430\u0442\u0432\u0438\u044e \u0447\u0435\u0440\u0435\u0437 \u0433\u043e\u0434.</td>\n</tr>\n<tr style=\"height: 15px\">\n<td style=\"width: 10.9543%;height: 15px\">\u041d\u0430\u0437\u0430\u0434</t